    "required_parts": [],
    "prerequisites": [
      "Use the exact-year diagrams to identify the adjusters and measurement points.",
      "Record current setup before changing it; do not force an adjuster past its stop.",
      "The stock preload ring and locknut must be reachable with suitable tools on the assembled bike. This guide does not remove or refit bodywork, the rear frame or the shock; complete any required access service separately before using it."
    ],
    "critical_stop_conditions": [
      "Unidentified component or adjuster; leaks, damage or binding; target setting cannot be reached within actual travel."
    ],
    "steps": [
      {
        "id": "inspect",
        "title": "Prepare the measurement",
        "instruction": "Check the shock for leaks and verify smooth suspension/linkage movement. Use level ground and a helper to stabilize the bike and take consistent readings.",
        "source_pdf_pages": [
          115
        ],
        "source_links": [
          "https://library.ymcapps.net/library/om/contents/pdf/10/D01-2819U-10_02.pdf#page=115"
        ],
        "diagram_reference_required": true,
        "record_required": true,
        "verification": [
          "Save the actual measurements or setting and outcome."
        ],
        "depends_on": []
      },
      {
        "id": "unloaded",
        "title": "Measure the unloaded bike",
        "instruction": "Support the bike under the engine so the rear wheel is off the floor. Measure A from the rear axle center to the molded reference mark on the rear fender shown in the diagram. Use the illustrated points and record the actual millimeters.",
        "source_pdf_pages": [
          388
        ],
        "source_links": [
          "https://library.ymcapps.net/library/om/contents/pdf/10/D01-2819U-10_02.pdf#page=388"
        ],
        "diagram_reference_required": true,
        "record_required": true,
        "verification": [
          "Save the actual measurements or setting and outcome."
        ],
        "depends_on": [
          "inspect"
        ]
      },
      {
        "id": "loaded",
        "title": "Measure with the rider",
        "instruction": "Remove the stand and have the rider sit astride the seat as shown. With the bike held upright, measure B between the same axle center and the molded reference mark on the rear fender shown in the diagram. Record the actual millimeters.",
        "source_pdf_pages": [
          388
        ],
        "source_links": [
          "https://library.ymcapps.net/library/om/contents/pdf/10/D01-2819U-10_02.pdf#page=388"
        ],
        "diagram_reference_required": true,
        "record_required": true,
        "verification": [
          "Save the actual measurements or setting and outcome."
        ],
        "depends_on": [
          "unloaded"
        ]
      },
      {
        "id": "assess",
        "title": "Calculate rider sag",
        "instruction": "Subtract B from A. The standard difference is 90–100 mm. Record both measurements, the difference and whether it is in range.",
        "source_pdf_pages": [
          388
        ],
        "source_links": [
          "https://library.ymcapps.net/library/om/contents/pdf/10/D01-2819U-10_02.pdf#page=388"
        ],
        "diagram_reference_required": true,
        "record_required": true,
        "verification": [
          "Save the actual measurements or setting and outcome."
        ],
        "depends_on": [
          "loaded"
        ]
      },
      {
        "id": "preload",
        "title": "Measure and adjust preload",
        "instruction": "With the rear wheel raised securely, clean dirt from the locknut and adjusting ring. Loosen the locknut and back off the ring until there is clearance to the spring; measure its free length. Turn the ring in diagram direction b to increase preload or c to decrease it. One turn changes installed length by 1.5 mm. Keep compression from free length within 1.5–18.0 mm; the standard starting preload is 8.0 mm. Record free length, installed length and resulting preload.",
        "source_pdf_pages": [
          115,
          116
        ],
        "source_links": [
          "https://library.ymcapps.net/library/om/contents/pdf/10/D01-2819U-10_02.pdf#page=115",
          "https://library.ymcapps.net/library/om/contents/pdf/10/D01-2819U-10_02.pdf#page=116"
        ],
        "diagram_reference_required": true,
        "record_required": true,
        "verification": [
          "Save the actual measurements or setting and outcome."
        ],
        "depends_on": [
          "assess"
        ]
      },
      {
        "id": "lock",
        "title": "Secure the setting",
        "instruction": "Tighten the preload locknut against the adjuster to secure the setting before loading the bike.",
        "source_pdf_pages": [
          116
        ],
        "source_links": [
          "https://library.ymcapps.net/library/om/contents/pdf/10/D01-2819U-10_02.pdf#page=116"
        ],
        "diagram_reference_required": true,
        "record_required": false,
        "verification": [
          "Confirm the action is complete."
        ],
        "depends_on": [
          "preload"
        ]
      },
      {
        "id": "remeasure",
        "title": "Repeat and record the result",
        "instruction": "Repeat the unloaded A and rider-loaded B measurements at the same points. Adjust within the allowed preload range until A minus B is 90–100 mm, tightening the locknut before each loaded measurement. If the target cannot be obtained within the allowed range, the spring must be changed and the setup repeated in a separate replacement operation. Save the final values; reevaluate after break-in.",
        "source_pdf_pages": [
          115,
          116,
          388,
          389
        ],
        "source_links": [
          "https://library.ymcapps.net/library/om/contents/pdf/10/D01-2819U-10_02.pdf#page=115",
          "https://library.ymcapps.net/library/om/contents/pdf/10/D01-2819U-10_02.pdf#page=116",
          "https://library.ymcapps.net/library/om/contents/pdf/10/D01-2819U-10_02.pdf#page=388",
          "https://library.ymcapps.net/library/om/contents/pdf/10/D01-2819U-10_02.pdf#page=389"
        ],
        "diagram_reference_required": true,
        "record_required": true,
        "verification": [
          "Save the actual measurements or setting and outcome."
        ],
        "depends_on": [
          "lock"
        ]
      }
    ]
